/**
 * @method
 * @name scwin.tx_fn_DigitalChangePage
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_DigitalChangePage = async function () {
    const sbmOptions = {
        id: "tx_fn_DigitalChangePage",
        method: "post",
        action: "/digital/DigitalList.do",
        ref: "dma_DigitalChangePageReq",
        target: "dlt_audtOpinTp=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil71903.tx_fn_DigitalChangePage" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_Search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/digital/DigitalList.do",
        ref: "dma_SearchReq",
        target: "dlt_audtOpinTp=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil71903.tx_fn_Search" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.digitalChangePage
 * @author Inswave
 * @date 2026. 09. 29
 * @param tab
 * @returns
 * @hidden N
*/
scwin.digitalChangePage = async function (tab) {
    /* sdd-asis-lifecycle:begin fn_DigitalChangePage — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form = (document.digitalListForm || { elements: [] });
    const lastSaveStatCdInt = parseInt($c.util.getComponent('dma_DigitalChangePageReq').get('lastSaveStatCd'));
    if (tab == 1) {
        $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'viewIsuTab');
    } else {
        if (tab == 2) {
            return;
        } else {
            if (tab == 3) {
                $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'viewSrtyLpTab');
            } else {
                $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'viewAttachFileTab');
            }
        }
    }
    scwin.form.action = 'DigitalList.do';
    await scwin.tx_fn_DigitalChangePage();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form = (document.digitalListForm || { elements: [] });
    scwin.form.action = "DigitalList.do";
    $c.util.getComponent('dma_DigitalChangePageReq').set('listBzTpCd', "");
    $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'searchList');
    await scwin.tx_fn_Search();
    /* sdd-asis-lifecycle:end */
};


